// Selections are grouped exactly like the paper version — FIXTURES / PLUMBING / ELECTRICAL /
// FLOOR & WALL COVERING — each its own color so the board reads at a glance. Any category
// name from any room's guide gets sorted into one of these by keyword; anything genuinely
// unclassifiable (a doors & hardware line, say) falls into "Other."
const SELECTION_GROUPS = ['Fixtures', 'Plumbing', 'Electrical', 'Floor & Wall Covering', 'Exterior'];
const SELECTION_ROOM_PRESETS = ['Kitchen', 'Primary Bath', 'Hall Bath', 'Powder Room', 'Basement', 'Whole House', 'Exterior', 'Other'];
const SELECTION_GROUP_COLORS = {
  'Fixtures': { accent: '#C9A227', bg: '#FBF6DD', text: '#8A7016' },
  'Plumbing': { accent: '#4A6FA5', bg: '#E8EFF7', text: '#33507A' },
  'Electrical': { accent: '#4A9B5E', bg: '#E7F3EA', text: '#2E6B3D' },
  'Floor & Wall Covering': { accent: '#8B5FBF', bg: '#F1E9F7', text: '#63428A' },
  'Exterior': { accent: '#B23B3B', bg: '#FBEAEA', text: '#8A2C2C' },
};
function selectionGroupFor(category) {
  // An item added from inside a specific dropdown (Fixtures, Plumbing, etc.) is tagged with
  // that group's exact name — honor that directly rather than re-guessing from keywords, since
  // the keyword guesser below gets "Electrical" itself wrong (no "light" in the word).
  if (SELECTION_GROUPS.includes(category)) return category;
  const c = (category || '').toLowerCase();
  if (c.includes('exterior') || c.includes('siding') || c.includes('roof') || c.includes('deck') || c.includes('porch') || c.includes('landscap') || c.includes('driveway') || c.includes('garage door') || c.includes('gutter')) return 'Exterior';
  if (c.includes('tile') || c.includes('floor') || c.includes('wallcovering') || c.includes('wall covering') || c.includes('backsplash')) return 'Floor & Wall Covering';
  if (c.includes('plumbing')) return 'Plumbing';
  if (c.includes('light')) return 'Electrical';
  return 'Fixtures';
}

