// Lets an estimator type "10k" instead of "10000" in any Budgets & Proposals dollar field.
// Accepts trailing k/K (with or without a space, with or without decimals — "2.5k" -> 2500).
const parseMoneyShorthand = (raw) => {
  if (raw == null) return '';
  const str = String(raw).trim();
  const match = str.match(/^(-?\d*\.?\d+)\s*[kK]$/);
  if (match) {
    const num = parseFloat(match[1]) * 1000;
    return String(Math.round(num));
  }
  return str;
};

