          display: 'flex', alignItems: 'center', gap: isSplash ? 10 : 8, border: 'none',
          background: '#808080', color: '#fff',
          borderRadius: 99, padding: isSplash ? '14px 36px' : '8px 16px', cursor: 'pointer', fontFamily: 'inherit',
          fontSize: isSplash ? 15 : 13, fontWeight: 500,
